const contrasena = pass();
cy.intercept({
  method: 'POST',
  url: /\/sesiones\/?$/
}).as('loginAdmin');
cy.visit(`${TEST_FRONT}/login`);
cy.get('input[type="email"]').clear().type(ADMIN);
cy.get('input[type="password"]').clear().type(contrasena, {
  log: false
});
cy.get('button[type="submit"]').contains(/ingresar/i).click();
cy.wait('@loginAdmin', {
  log: false
}).then(intc => {
  const http = intc.response && intc.response.statusCode;
  const tok = intc.response && intc.response.body && intc.response.body.token;
  return cy.writeFile(`${EVIDENCIA}/G94-178-rev4-login.json`, {
    http,
    token_presente: typeof tok === 'string' && tok.length > 0,
    nota: 'Sin cuerpo de sesión ni token. Solo lectura posterior.'
  }).then(() => {
    expect(http, `login admin UI HTTP (observado=${http == null ? 'null' : http})`).to.eq(200);
    expect(tok, `token admin tras login HTTP ${http} (observado=${tok == null ? 'null' : typeof tok})`).to.be.a('string').and.not.empty;
    tokenAdmin = tok;
    lastStep = 'login_admin_ui';
  });
});
cy.url({
  timeout: 20000
}).should('include', '/dashboard').and('not.include', '/login').then(() => {
  lastStep = 'dashboard';
});
cy.then(() => {
  expect(tokenAdmin, `token antes de GET autenticados (last_step=${lastStep}, observado=${tokenAdmin == null ? 'null' : typeof tokenAdmin}). No se continúa sin token.`).to.be.a('string').and.not.empty;
});
apiGetLectura('/configuracion/personalizacion/tema').then(temaRes => {
